_choice_field() {
    top -O 2>/dev/null
}

_choice_pid() {
    command -v ps >/dev/null || return 0
    ps -eo pid=,comm= | gawk 'NF >= 2 {
        pid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print pid "\t" $0
    }'
}

_choice_scale_summary_mem() {
    printf '%s\n' k m g t p e
}

_choice_scale_task_mem() {
    printf '%s\n' k m g t p
}

_choice_user() {
    command -v ps >/dev/null || return 0
    ps -eo user= | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d'
}
